            'font-size="70" fill="' + color + '" opacity="0.6" letter-spacing="3">评论</text>' +
            '</svg>';
    }
    // 默认返回样式0
    else {
        svg = '<svg width="160" height="120" xmlns="http://www.w3.org/2000/svg">' +
            '<path d="M 55 10 ' +
            'L 120 10 ' +
            'Q 150 10 150 40 ' +
            'L 150 80 ' +
            'Q 150 110 120 110 ' +
            'L 55 110 ' +
            'Q 25 110 25 80 ' +
            'L 25 75 ' +
            'L 3 60 ' +
            'L 25 45 ' +
            'L 25 40 ' +
            'Q 25 10 55 10 Z" ' +
            'fill="none" ' +
            'stroke="' + color + '" ' +
            'stroke-width="2" ' +
            'stroke-linejoin="round"/>' +
            '<!-- 数字文本 -->' +
            '<text x="87" y="75" ' +
            'font-family="Arial, sans-serif" ' +
            'text-anchor="middle" ' +
            'dominant-baseline="middle" ' +
            'font-size="50" ' +
            'font-weight="bold" ' +
            'fill="' + color + '">' +
            displayText +
