//设置音色
function set_tone_id(mode, name) {
    putLoginInfo(JSON.stringify(result))
    let zdytone_id;
    try {
        zdytone_id = String(result['其他音色填写后点击右上角✔']);
        if (zdytone_id) {
            setArgument('tone_id', zdytone_id);
            java.toast(`\n\n当前音色为自定义音色\n${zdytone_id}\n\n切换音色请先清空音色输入框中的数据`);
        } else {
            zdytone_id = '';
        }
    } catch (error) {
        zdytone_id = '';
    }
    if (!zdytone_id) {
        let toast = "\n\n已切换至：" + name + '\n\n切换后需要刷新详情页';
        setArgument('tone_id', mode);
        java.toast(toast);
    }
}

//设置来源
function set_source(sources) {
    let zdysources = String(result['自定义搜索源(多个用英文,分割)'] || '');
    if (zdysources.length > 1 && zdysources != 'undefined') {
        java.toast('\n\n请先清空自定义源再设置');
    } else {
        setArgument('source', sources);
        set_media('小说');
        java.toast(`\n\n当前来源已切换为:\n${sources}\n\n切换后请重新搜索`);
    }
}

// 设置简介
function set_info() {
